	ida_struct.set_member_cmt(ida_struct.get_member(struc, 172936), '''List<(String, String)>(104) [Record(String, String) = ("倒轮换三指", "演奏倒轮的同时，左手食、中、名三指在同一徽位同时换指配合。"), Record(String, String) = ("掐拨剌三声", "除将撮改为拨剌外，其余与掐撮三声相同。"), Record(String, String) = ("搯拨剌三声", "除将撮改为拨剌外，其余与掐撮三声相同。"), Record(String, String) = ("掐撮三声", "先作掐撮；大指再掩、掐起两次，先正后反；最后右手再撮一声，共八声。"), Record(String, String) = ("搯撮三声", "先作搯撮；大指再掩、搯起两次，先正后反；最后右手再撮一声，共八声。"), Record(String, String) = ("摘拨剌", "名指摘双弦如一声后，立即接奏拨剌。"), Record(String, String) = ("缓急吟", "同音高的连续两音，先缓后急，分别作两次揉弦。"), Record(String, String) = ("落指吟", "得音后立即揉弦，不留间隙。"), Record(String, String) = ("落指猱", "用法似落指吟，但左手揉弦幅度稍大。"), Record(String, String) = ("长猱", "用法似长吟，但左手揉弦幅度稍大。"), Record(String, String) = ("绰猱", "用法似绰吟，但左手揉弦幅度稍大。"), Record(String, String) = ("注猱", "用法似注吟，但左手揉弦幅度稍大。"), Record(String, String) = ("荡猱", "用法似荡吟，但左手揉弦幅度稍大。"), Record(String, String) = ("略猱", "用法似略吟，但左手揉弦幅度稍大。"), Record(String, String) = ("缓猱", "用法似缓吟，但左手揉弦幅度稍大。"), Record(String, String) = ("急猱", "用法似急吟，但左手揉弦幅度稍大。"), Record(String, String) = ("撞猱", "先作双撞，再接猱。"), Record(String, String) = ("迎猱", "作连贯、柔缓且幅度较大的揉弦。"), Record(String, String) = ("长吟", "作时值较长的小幅度揉弦。"), Record(String, String) = ("定吟", "在本音位不作移位的揉弦。"), Record(String, String) = ("绰吟", "先作绰，再接吟。"), Record(String, String) = ("注吟", "先作注，再接吟。"), Record(String, String) = ("细吟", "作幅度小、速度快的揉弦。"), Record(String, String) = ("游吟", "作带有小幅度进复的慢揉弦。"), Record(String, String) = ("荡吟", "用法同游吟，但在进复中加重音头。"), Record(String, String) = ("急吟", "作急速的小幅度揉弦。"), Record(String, String) = ("缓吟", "作缓慢的小幅度揉弦。"), Record(String, String) = ("少吟", "在本音中稍作揉弦。"), Record(String, String) = ("略吟", "在吟的过程中略作揉弦。"), Record(String, String) = ("双吟", "同音高的先后两音都作揉弦。"), Record(String, String) = ("飞吟", "得音后，向上与向下揉弦交替进行。"), Record(String, String) = ("长琐", "先作抹挑，少息后接短琐，得七声；也可作九声：抹勾抹挑抹勾剔抹挑，或抹挑勾剔抹挑剔抹挑。"), Record(String, String) = ("短琐", "同弦先作抹勾，再作剔抹挑，共五声；也可作抹挑抹勾挑。"), Record(String, String) = ("背琐", "同弦用剔、抹、挑急作三声。"), Record(String, String) = ("叠涓", "同弦用食、中两指先抹后勾，急连相逐得音。"), Record(String, String) = ("叠蠲", "同弦用食、中两指先抹后勾，急连相逐得音。"), Record(String, String) = ("反涓", "先剔后挑，或先打后勾，一重一轻，急奏二声。"), Record(String, String) = ("反蠲", "先剔后挑，或先打后勾，一重一轻，急奏二声。"), Record(String, String) = ("半涓", "同弦先抹后轻勾，略有声，与叠涓稍有区别。"), Record(String, String) = ("半蠲", "同弦先抹后轻勾，略有声，与叠蠲稍有区别。"), Record(String, String) = ("连涓", "同弦先剔后勾，两声急连。"), Record(String, String) = ("连蠲", "同弦先剔后勾，两声急连。"), Record(String, String) = ("涓", "有两种方法：一是同弦先抹后勾；二是抹过相并两弦，中指随即按煞前弦，此法又名“分搂”。"), Record(String, String) = ("蠲", "有两种方法：一是同弦先抹后勾；二是抹过相并两弦，中指随即按煞前弦，此法又名“分搂”。"), Record(String, String) = ("双弹", "两弦一按一散，中、食二指次第弹出，作两个如一之声。"), Record(String, String) = ("三弹", "两弦一按一散，名、中、食三指次第弹出，作三个如一之声。"), Record(String, String) = ("全扶", "右手食指先连抹相邻两弦，然后中指再连勾这两弦。"), Record(String, String) = ("半扶", "右手食指先连抹相邻两弦，然后中指顺势止住第一弦余音。"), Record(String, String) = ("圆搂", "用食、中两指同时抹勾双弦。"), Record(String, String) = ("拍杀", "先奏拨剌，再接以伏。"), Record(String, String) = ("大间勾", "隔两弦作勾挑。"), Record(String, String) = ("小间勾", "隔一弦作勾挑。"), Record(String, String) = ("掐撮", "左手名指按弦，大指在上一音位掩、掐起后，右手随即撮一声。"), Record(String, String) = ("搯撮", "左手名指按弦，大指在上一音位掩、搯起后，右手随即撮一声。"), Record(String, String) = ("转圆", "滚拂连用，循环不停。"), Record(String, String) = ("滚拂", "先滚后拂。"), Record(String, String) = ("双撞", "连续作撞两次。"), Record(String, String) = ("反撞", "左手得声后立即注下稍许，再归本位，比退复快。"), Record(String, String) = ("小撞", "作幅度较小的撞。"), Record(String, String) = ("虚撞", "不弹弦，只作撞的动作。"), Record(String, String) = ("进复", "得音后，左手上下往复一次。"), Record(String, String) = ("退复", "得音后先下后上，往复一次。"), Record(String, String) = ("推出", "左手中指向外斜推拨一弦。"), Record(String, String) = ("放合", "左手名指向内放开空弦并随即按于次弦某音位时，右手拨该弦一声。"), Record(String, String) = ("抓合", "左手大指按于某弦后，名指拨另一弦得声时随即抓起，形成和音。"), Record(String, String) = ("带合", "同声的一种，专指左手用名指拨弦。"), Record(String, String) = ("抓起", "左手大指向上带弦得声。"), Record(String, String) = ("带起", "左手名指向上带弦得声。"), Record(String, String) = ("掐起", "左手名指按弦，大指拨弦得声。"), Record(String, String) = ("搯起", "左手名指按弦，大指拨弦得声。"), Record(String, String) = ("如一", "两弦一按一散，同时剔出，如同一声。"), Record(String, String) = ("琐", "依次作抹、挑、抹。"), Record(String, String) = ("倒轮", "同弦用食、中、名三指次第急连入弦，得三声。"), Record(String, String) = ("半轮", "同弦用名、中二指次第急连触弦，得二声。"), Record(String, String) = ("轮", "同弦用名、中、食三指次第急连触弦，得三声。"), Record(String, String) = ("弹", "两弦相邻，一按一散，食指挑出，作如一之声。"), Record(String, String) = ("拨剌", "食、中、名三指先在双弦上斜向内拨奏，再向外斜拨。"), Record(String, String) = ("拨", "食、中、名三指同时在双弦上斜向内拨奏。"), Record(String, String) = ("剌", "食、中、名三指同时在双弦上向外斜拨。"), Record(String, String) = ("伏", "食、中、名三指在一二弦上向外剌出，同时伸直手指伏于弦上，遏住余音。"), Record(String, String) = ("挫", "中、食二指在同一弦上接连快速弹奏，几如一声。"), Record(String, String) = ("鼓", "重作双弹。"), Record(String, String) = ("大撮", "右手大、中两指托勾并作，同得一声。"), Record(String, String) = ("反撮", "与撮相反，右手剔抹并作，同得一声。"), Record(String, String) = ("撮", "右手食、中两指勾挑并作，同得一声。"), Record(String, String) = ("扫", "左手按一二弦，右手食、中、名三指带相邻空弦剌出，得一声。"), Record(String, String) = ("仰托", "右手大指仰卧挑弦，得一煞声。"), Record(String, String) = ("捻", "右手大、食两指捻弦提起后放开，使弦击琴面得一煞声。"), Record(String, String) = ("打圆", "右手食、中两指在两弦上次第勾挑交错，得七声。"), Record(String, String) = ("渡", "用法与历相似，但速度稍缓。"), Record(String, String) = ("临", "右手食指由七弦连挑至二弦，如历法，专用于泛音。"), Record(String, String) = ("历", "右手食指连挑过数弦。"), Record(String, String) = ("雷", "右手食指连挑或名指连摘，如滚状但放缓，逐声弹出，声如雷之殷殷。"), Record(String, String) = ("滚", "右手名指连摘相邻数弦。"), Record(String, String) = ("拂", "右手食指连抹相邻数弦。"), Record(String, String) = ("牵", "用法同勾，但下指较重。"), Record(String, String) = ("猱", "得音后，左手作移动幅度较大的揉弦。"), Record(String, String) = ("吟", "左手作幅度较小的揉弦。"), Record(String, String) = ("绰", "左手从相邻低音位上滑至本音位。"), Record(String, String) = ("注", "左手从相邻高音位下滑至本音位。"), Record(String, String) = ("撞", "左手得声后绰上稍许，立即归本位，比进复快。"), Record(String, String) = ("唤", "用法似撞，但动作较柔和。"), Record(String, String) = ("逗", "通常与唤不分；有时左手可上滑稍高于本位，再回归。"), Record(String, String) = ("浒", "左手按弦得音，稍后引上至下一音位。")]''', True)
