	ida_struct.set_member_cmt(ida_struct.get_member(struc, 129576), '''AnonymousClosure: static (0x616b24), in [package:lingling/src/features/tanba/services/sentence_pitch_analyzer.dart] SentencePitchAnalyzer::analyze (0x616b9c)''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 129568), '''String: "这次更适合当作定位问题的练习记录，慢练会比反复通弹更有效。"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 129560), '''String: "已经有不错的稳定性，再把弱句磨平会明显提升。"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 129552), '''String: "整体完成度很高，可以继续追求更细腻的收放和余韵。"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 129544), '''String: "，建议单独多练。"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 129536), '''String: "需要加强的句子："''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 129528), '''String: "没有特别拖后腿的句子，继续保持整曲连贯。"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 129520), '''String: "。"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 129512), '''String: "表现较好的句子："''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 129504), '''String: "暂时没有特别稳定的句子，先把前两句练扎实。"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 129496), '''String: "节奏偏差较大，建议先按句练起音，不急着连完整曲。"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 129488), '''String: "节奏基本能跟上，但快慢还不够均匀，建议开节拍器慢速练。"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 129472), '''String: "节奏进入比较稳，起音时机清楚。"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 129456), '''String: "音准偏差较明显，建议先慢练单句，确认每个音的徽位再连起来。"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 129448), '''String: "音准有基础，但部分音偏差偏大，留意徽位和按弦落点。"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 129440), '''String: "音准整体稳定，按弦位置控制得比较准。"''', True)
